(3430891, 479242, 57378, '<td valign="top">Nice capture - Lovely moody sky.</td>', 'Nice capture - Lovely moody sky.', '2007-03-05 14:27:48.000000', NULL, 1),
(3430896, 476965, 57378, '<td valign="top">Nice capture- Love the simplicity of it and the sand tones are great. One thing though that distracts me as soon as I see this and it''s the cloud touching the back of the chair - I know it''s a minor point and a bit niggly but if you look at it closely with all these great crisp lines and simple balance it just throws it off for me - Still a great shot though and I love the blue/black PP</td>', 'Nice capture- Love the simplicity of it and the sand tones are great. One thing though that distracts me as soon as I see this and it''s the cloud touching the back of the chair - I know it''s a minor point and a bit niggly but if you look at it closely with all these great crisp lines and simple balance it just throws it off for me - Still a great shot though and I love the blue/black PP', '2007-03-05 14:30:11.000000', NULL, 1),
(3430906, 479477, 57378, '<td valign="top">Nice capture - How very art deco! Lovely lighting.</td>', 'Nice capture - How very art deco! Lovely lighting.', '2007-03-05 14:35:28.000000', NULL, 1),
