(3430910, 479467, 57378, '<td valign="top">Nice capture - Next time though get that white background further away to get rid of those annoying shadows. It really will help make the image stand out. You can see where the chair meets the paper on the left hand side and it''s distracting.</td>', 'Nice capture - Next time though get that white background further away to get rid of those annoying shadows. It really will help make the image stand out. You can see where the chair meets the paper on the left hand side and it''s distracting.', '2007-03-05 14:37:34.000000', NULL, 1),
(3430913, 475695, 57378, '<td valign="top">Nice capture- Very simple and calming - I like it  a lot.</td>', 'Nice capture- Very simple and calming - I like it  a lot.', '2007-03-05 14:37:57.000000', NULL, 1),
(3430915, 478171, 57378, '<td valign="top">Nice capture - Nice light. Maybe just a tad boring. Sorry to use that word but that''s what comes to mid when I see it.</td>', 'Nice capture - Nice light. Maybe just a tad boring. Sorry to use that word but that''s what comes to mid when I see it.', '2007-03-05 14:38:41.000000', NULL, 1),
