(3430982, 479147, 57378, '<td valign="top">Great capture -  like the spot light effect on the couch - Would have liked to see the leg in there though.</td>', 'Great capture -  like the spot light effect on the couch - Would have liked to see the leg in there though.', '2007-03-05 15:10:31.000000', NULL, 1),
(3430987, 478982, 57378, '<td valign="top">Great capture - Love the contemporary feel to this. The wood colours in the walkway are great and the chair is of the same feel. For me (And this is all subjective and personal) I would have placed the chair really close in the right hand side so that it fitted into the clouds just there and had it on an angle towards me. Just so there was a little difference between the shed and chair - I know what you are going for here with the clean cut lines etc but just think it may have added a little more dynamic to the pic. Still a great shot though. Looks like a great location.</td>', 'Great capture - Love the contemporary feel to this. The wood colours in the walkway are great and the chair is of the same feel. For me (And this is all subjective and personal) I would have placed the chair really close in the right hand side so that it fitted into the clouds just there and had it on an angle towards me. Just so there was a little difference between the shed and chair - I know what you are going for here with the clean cut lines etc but just think it may have added a little more dynamic to the pic. Still a great shot though. Looks like a great location.', '2007-03-05 15:14:21.000000', NULL, 1),
(3430988, 479454, 57378, '<td valign="top">Great capture - nice and crisp</td>', 'Great capture - nice and crisp', '2007-03-05 15:14:35.000000', NULL, 1),
