(3446676, 479477, 67152, '<td valign="top">what a cool chair...the lighting on this image to bring out the angular look works very well</td>', 'what a cool chair...the lighting on this image to bring out the angular look works very well', '2007-03-09 14:19:12.000000', NULL, 1),
(3446689, 479186, 67152, '<td valign="top">The sky is nice - I like the color and the soft clouds in the background, but the lighting on the chair just seems too dark.  In addition, the lighting on the chair seems to be coming from the opposite direction as the lighting in the sky.  The right side of the sky is brighter than the left, but the lower left side of the chair is brighter than the right....5</td>', 'The sky is nice - I like the color and the soft clouds in the background, but the lighting on the chair just seems too dark.  In addition, the lighting on the chair seems to be coming from the opposite direction as the lighting in the sky.  The right side of the sky is brighter than the left, but the lower left side of the chair is brighter than the right....5', '2007-03-09 14:25:47.000000', NULL, 1),
(3446692, 477119, 67152, '<td valign="top">The concept on the photo is pretty good, but the coloring on the chairs, with the orangish coloring on the finish, really detracts.  4</td>', 'The concept on the photo is pretty good, but the coloring on the chairs, with the orangish coloring on the finish, really detracts.  4', '2007-03-09 14:27:49.000000', NULL, 1),
(3446701, 479446, 67152, '<td valign="top">The tones in the wood are very nice - but the lighting (I assume an on camera flash) really creative an uneven feel.  The harsh lighting seems more of a snapshot.</td>', 'The tones in the wood are very nice - but the lighting (I assume an on camera flash) really creative an uneven feel.  The harsh lighting seems more of a snapshot.', '2007-03-09 14:31:36.000000', NULL, 1),
(3446705, 478987, 67152, '<td valign="top">I like the perspective a good deal - but I am not a fan of how this was processed.  There appear to be significant halos above the trees along the path and the image has such a flat feel.  4</td>', 'I like the perspective a good deal - but I am not a fan of how this was processed.  There appear to be significant halos above the trees along the path and the image has such a flat feel.  4', '2007-03-09 14:32:48.000000', NULL, 1),
(3446712, 479191, 67152, '<td valign="top">What we do for DPC!  Nice photo  - love the fact that the lamp looks like it is on (hopefully it was not actually plugged in!).  6</td>', 'What we do for DPC!  Nice photo  - love the fact that the lamp looks like it is on (hopefully it was not actually plugged in!).  6', '2007-03-09 14:35:17.000000', NULL, 1),
(3446715, 479476, 67152, '<td valign="top">At first I didn''t notice the size difference!  Nice B/W image with good grey tones and highlights. 7</td>', 'At first I didn''t notice the size difference!  Nice B/W image with good grey tones and highlights. 7', '2007-03-09 14:36:11.000000', NULL, 1),
(3446723, 479192, 67152, '<td valign="top">This is a great piece of furniture, but it needs some different lighting to bring out the great tones and details.</td>', 'This is a great piece of furniture, but it needs some different lighting to bring out the great tones and details.', '2007-03-09 14:37:13.000000', NULL, 1),
(3446724, 478299, 67152, '<td valign="top">Very nice macro on wicker - that is some cool colors you have shown us!</td>', 'Very nice macro on wicker - that is some cool colors you have shown us!', '2007-03-09 14:38:00.000000', NULL, 1),
(3446739, 479429, 67152, '<td valign="top">Nice balancing act! But... the lighting with the shadows all over the place and the bright spot on the backgound and not on the man''s face draws my attention away from the action.  4</td>', 'Nice balancing act! But... the lighting with the shadows all over the place and the bright spot on the backgound and not on the man''s face draws my attention away from the action.  4', '2007-03-09 14:41:25.000000', NULL, 1),
