(4242306, 478299, 43463, '<td valign="top">Lighting is really spot on with this composition. I clearly illuminates all the interesting lines of this ordinary everyday object. The angle you composed this photo also heightens the visual interest and makes the everyday ordinary object and extraordinary study of lines, shapes and angles. Love the play of light and shadows.</td>', 'Lighting is really spot on with this composition. I clearly illuminates all the interesting lines of this ordinary everyday object. The angle you composed this photo also heightens the visual interest and makes the everyday ordinary object and extraordinary study of lines, shapes and angles. Love the play of light and shadows.', '2007-11-12 21:18:37.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4255678, 479466, 63269, '<td valign="top">Awesome... you''ve captured the perfect creepy night-time feel here. Reading through the other coments... IMO, it is NOT too dark! ;) If anything, I would have actually made the subject slightly <i>darker</i>, so he and the chair don''t pop out quite so much. More subtle that way. Very neat shot, and very neat idea!</td>', 'Awesome... you''ve captured the perfect creepy night-time feel here. Reading through the other coments... IMO, it is NOT too dark! ;) If anything, I would have actually made the subject slightly darker, so he and the chair don''t pop out quite so much. More subtle that way. Very neat shot, and very neat idea!', '2007-11-18 16:01:21.000000', NULL, 0),
(4312807, 479254, 63398, '<td valign="top">I really like the way you work low light and muted colors along with negative space to create these haunting, evocative images. Stellar.</td>', 'I really like the way you work low light and muted colors along with negative space to create these haunting, evocative images. Stellar.', '2007-12-13 11:58:49.000000', NULL, 0),
